pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(0x1234);
        c.addReward(rewardToken);

        uint256 bal = c.balanceOf(address(this));
        assertTrue(bal == 0, "Expected balance to be 0");
    }
